// Copies agent/eval-results.json → web/public/proof/eval-results.json when the source is newer.
// The committed copy in web/public/proof/ is what ships to production: `railway up` respects gitignore,
// and agent/eval-results.json is gitignored (it is regenerated by `npm run eval`).
import { access, copyFile, mkdir, stat } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const src = resolve(here, '../../agent/eval-results.json');
const dst = resolve(here, '../public/proof/eval-results.json');

try {
  await access(src);
  const s = await stat(src);
  const d = await stat(dst).catch(() => null);
  if (!d || s.mtimeMs > d.mtimeMs) {
    await mkdir(dirname(dst), { recursive: true });
    await copyFile(src, dst);
    console.log('[prebuild] eval-results.json → web/public/proof/ (fresh copy)');
  }
} catch {
  console.warn('[prebuild] agent/eval-results.json not found — shipping the committed copy');
}
